import "aos/dist/aos.css";
import { FaTrademark } from "react-icons/fa";
import AppContext from "../../../../Context";
import { useContext } from "react";

export default function Trademark() {
    const { language } = useContext(AppContext);
    const registrationTypes = [
        language === "id" ? "Individu Indonesia (WNI)" : "Indonesian Individual (WNI)",
        language === "id" ? "Individu Asing (WNA)" : "Foreign Individual (WNA)",
        language === "id" ? "Perusahaan Dalam Negeri (PMDN)" : "Domestic Company (PMDN)",
        language === "id"
            ? "Perusahaan Penanaman Modal Asing (PMA) di Indonesia"
            : "Foreign Investment Company (PMA) in Indonesia",
        language === "id" ? "Perusahaan Asing (Luar Negeri)" : "Foreign Company (Overseas)",
    ];

    const scope = [
        language === "id"
            ? "Penelusuran & Analisa Merek Oleh Tim Ahli"
            : "Trademark Search & Analysis by Our Expert Team",

        language === "id"
            ? "Penentuan Katagori Kelas ( dari 45 Kelas Barang & Jasa )"
            : "Determination of the Appropriate Class Category (from 45 Classes of Goods & Services)",

        language === "id"
            ? "Pengajuan Permohonan Pendaftaran Merek ke DJKI"
            : "Submission of Trademark Registration Application to DGIP",

        language === "id"
            ? "Penyerahan Tanda Terima Permohonan Merek dari DJKI"
            : "Delivery of the Trademark Application Receipt Issued by DGIP",

        language === "id"
            ? "Gratis Penyusunan & Pengajuan Tanggapan Pertama atas Oposisi atau Keberatan"
            : "Free Preparation & Submission of the First Response to Any Opposition or Objection",

        language === "id"
            ? "Layanan Konsultasi Merek 24/7"
            : "24/7 Trademark Consultation Services",
    ];

    const timeline = [
        language === "id"
            ? "Penelusuran & Analisa Merek – 1 Hari Kerja"
            : "Trademark Search & Analysis – 1 Working Day",

        language === "id"
            ? "Persiapan Surat Kuasa & Summary – 1 Hari Kerja"
            : "Preparation of Power of Attorney & Summary – 1 Working Day",

        language === "id"
            ? "Pengajuan Pendaftaran Merek – 1 Hari Kerja"
            : "Trademark Registration Filing – 1 Working Day",

        language === "id"
            ? "Bukti Tanda Terima Permohonan – 1 Hari Kerja"
            : "Issuance of Trademark Application Receipt – 1 Working Day",
    ];

    const requirements = [
        {
            title:
                language === "id"
                    ? "PERSYARATAN PENDAFTARAN MEREK ATASNAMA PRIBADI WNI"
                    : "REQUIREMENTS FOR TRADEMARK REGISTRATION UNDER THE NAME OF AN INDIVIDUAL INDONESIAN CITIZEN",
            items:
                language === "id"
                    ? ["KTP ( Kartu Tanda Penduduk )", "Logo & Nama Merek ", "Alamat Email Aktif"]
                    : ["Indonesian National ID card", "Logo & Trademark Name", "Email Address"],
        },
        {
            title:
                language === "id"
                    ? "PERSYARATAN PENDAFTARAN MEREK ATASNAMA PRIBADI WNA"
                    : "REQUIREMENTS FOR TRADEMARK REGISTRATION UNDER THE NAME OF AN INDIVIDUAL FOREIGN NATIONAL",
            items:
                language === "id"
                    ? ["Kartu Identitas Nasional yang Diterbitkan oleh Otoritas Berwenang di Negara Asal", "Valid Passport",
                        "Valid KITAS ( Limited Stay Permit Card )", "Logo & Nama Merek", "Alamat Email Aktif"]
                    : ["National Identity Card Issued by the Competent Authority in the Country of Origin", "A Valid Passport",
                        "Valid KITAP ( Permanent Stay Permit Card ) *if any", "Logo & Trademark Name", "Email Address"],
        },
        {
            title:
                language === "id"
                    ? "PERSYARATAN PENDAFTARAN MEREK ATASNAMA PERUSAHAAN PMDN"
                    : "REQUIREMENTS FOR TRADEMARK REGISTRATION UNDER THE NAME OF A DOMESTIC INVESTMENT COMPANY",
            items:
                language === "id"
                    ? [
                        "KTP ( Kartu Tanda Penduduk ) Direktur",
                        "NPWP Perusahaan",
                        "Akta Pendirian Perusahaan",
                        "Akta Perubahan Perusahaan",
                        "NIB ( Nomor Induk Berusaha )",
                        "SK Pendirian Perusahaan dari Kementerian",
                        "SK Perubahan Perusahaan dari Kementerian Hukum *if any",
                        "Logo & Nama Merek",
                        "Alamat Email Aktif"
                    ]
                    : [
                        "Director's ID card",
                        "Corporate Tax ID",
                        "Deed of Establishment of the Company",
                        "Deed of Amendment of the Company *if any",
                        "Business Identification Number",
                        "Approval Decree on the Establishment of the Company Issued by the Ministry of Law of the Republic of Indonesia",
                        "Approval Decree on the Amendment of the Company Issued by the Ministry of Law of the Republic of Indonesia",
                        "Logo & Trademark Name",
                        "Email Address"
                    ],
        },
        {
            title:
                language === "id"
                    ? "PERSYARATAN PENDAFTARAN MEREK ATAS NAMA PERUSAHAAN PMA DI INDONESIA"
                    : "REQUIREMENTS FOR TRADEMARK REGISTRATION UNDER THE NAME OF A FOREIGN COMPANY ( PMA ) IN INDONESIA",
            items:
                language === "id"
                    ? [
                        "KTP ( Kartu Tanda Penduduk ) Direktur / Kartu Identitas Nasional yang Diterbitkan oleh Otoritas Berwenang di Negara Asal",
                        "Valid Passport Direktur",
                        "Valid KITAS ( Limited Stay Permit Card )",
                        "Akta Pendirian Perusahaan",
                        "Akta Perubahan Perusahaan",
                        "NIB ( Nomor Induk Berusaha )",
                        "SK Pendirian Perusahaan dari Kementerian Hukum",
                        "SK Perubahan Perusahaan dari Kementerian Hukum *if any",
                        "Logo & Nama Merek",
                        "Alamat Email Aktif"
                    ]
                    : [
                        "Director's ID card / National Identity Card Issued by the Competent Authority in the Country of Origin",
                        "Valid Passport of the Director *if any",
                        "Valid KITAP ( Permanent Stay Permit Card ) *if any",
                        "Deed of Establishment of the Company",
                        "Deed of Amendment of the Company *if any",
                        "Business Identification Number",
                        "Approval Decree on the Establishment of the Company Issued by the Ministry of Law of the Republic of Indonesia",
                        "Approval Decree on the Amendment of the Company Issued by the Ministry of Law of the Republic of Indonesia",
                        "Logo & Trademark Name",
                        "Email Address"
                    ],
        },
        {
            title:
                language === "id"
                    ? "PERSYARATAN PENDAFTARAN MEREK ATAS NAMA PERUSAHAAN ASING DI LUAR NEGERI"
                    : "REQUIREMENTS FOR TRADEMARK REGISTRATION UNDER THE NAME OF A FOREIGN COMPANY ESTABLISHED ABROAD",
            items:
                language === "id"
                    ? [
                        "KTP ( Kartu Tanda Penduduk ) Direktur / Kartu Identitas Nasional yang Diterbitkan oleh Otoritas Berwenang di Negara Asal",
                        "Valid Passport Direktur",
                        "Valid KITAS ( Limited Stay Permit Card )",
                        "Akta Pendirian Perusahaan",
                        "Akta Perubahan Perusahaan",
                        "Lisensi Perusahaan dari Negara Asal",
                        "NPWP Perusahaan",
                        "Logo & Nama Merek",
                        "Alamat Email Aktif"
                    ]
                    : [
                        "Director's ID card / National Identity Card Issued by the Competent Authority in the Country of Origin																",
                        "Valid Passport of the Director *if any",
                        "Valid KITAP ( Permanent Stay Permit Card ) *if any",
                        "Deed of Establishment of the Company",
                        "Deed of Amendment of the Company *if any",
                        "Certificate of Business License from The Country of Origin",
                        "Corporate Tax ID																",
                        "Logo & Trademark Name",
                        "Email Address"
                    ],
        },
    ];

    return (
        <div className="pt-24">

            {/* HERO STYLE SECTION */}
            <section className="mb-24 bg-white">
                <div className="w-11/12 md:w-8/12 mx-auto text-center">

                    {/* ICON */}
                    <div
                        className="flex justify-center mb-6"
                        data-aos="zoom-in"
                    >
                        <div className="w-20 h-20 rounded-full bg-primary-blue-100 flex items-center justify-center">
                            <FaTrademark className="text-primary-blue-700 text-4xl" />
                        </div>
                    </div>

                    {/* TITLE */}
                    <h1
                        data-aos="fade-up"
                        className="text-3xl md:text-5xl font-bold text-primary-blue-900 mb-6"
                    >
                        {language === "id" ? "Pendaftaran Merek Dagang" : "Trademark Registration"}
                    </h1>

                    <p
                        data-aos="fade-up"
                        data-aos-delay="200"
                        className="text-gray-600 max-w-2xl mx-auto mb-16"
                    >
                        {language === "id"
                            ? "Lindungi identitas dan reputasi bisnis Anda melalui pendaftaran merek resmi di Direktorat Jenderal Kekayaan Intelektual (DJKI)."
                            : "Protect your business identity and reputation through official trademark registration with the Directorate General of Intellectual Property (DGIP)."}
                    </p>

                    {/* REGISTRATION TYPES */}
                    <div className="mb-24">
                        <h2
                            data-aos="fade-up"
                            className="text-2xl font-semibold text-primary-blue-900 mb-8"
                        >
                            {language === "id" ? "Jenis Pendaftaran" : "Registration Types"}
                        </h2>

                        <div className="flex flex-wrap justify-center gap-8">
                            {registrationTypes.map((item, index) => (
                                <div
                                    key={index}
                                    data-aos="fade-up"
                                    data-aos-delay={index * 100}
                                    className="
                                        w-full
                                        sm:w-[calc(33.333%-1.34rem)]
                                        bg-white rounded-xl border border-gray-200 p-6
                                        text-center
                                        transition-all duration-300 ease-in-out
                                        hover:shadow-xl hover:scale-105
                                    "
                                >
                                    <p className="font-semibold text-primary-blue-900">
                                        {item}
                                    </p>
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* SCOPE OF WORK */}
                    <div className="mb-24">
                        <h2
                            data-aos="fade-up"
                            className="text-2xl font-semibold text-primary-blue-900 mb-8"
                        >
                            {language === "id" ? "Ruang Lingkup Pekerjaan" : "Scope of Work"}
                        </h2>

                        <div className="flex flex-wrap justify-center gap-6 text-left">
                            {scope.map((item, index) => (
                                <div
                                    key={index}
                                    data-aos="fade-up"
                                    data-aos-delay={index * 100}
                                    className="
                                        w-full
                                        sm:w-[calc(33.333%-1.34rem)]
                                        bg-primary-blue-50 rounded-xl p-6
                                        transition-all duration-300
                                        hover:shadow-lg hover:scale-105
                                    "
                                >
                                    <p className="text-gray-700">
                                        {item}
                                    </p>
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* TIMELINE */}
                    <div className="mb-28">
                        <h2
                            data-aos="fade-up"
                            className="text-2xl font-semibold text-primary-blue-900 mb-16 text-center"
                        >
                            {language === "id"
                                ? "Tahapan Proses (Tahap Awal)"
                                : "Processing Timeline (Initial Stage)"}
                        </h2>

                        <div className="relative max-w-4xl mx-auto">

                            {/* Vertical Line */}
                            <div className="absolute left-4 md:left-1/2 top-0 bottom-0 w-px bg-gray-200"></div>

                            {timeline.map((item, index) => (
                                <div
                                    key={index}
                                    data-aos="fade-up"
                                    data-aos-delay={index * 100}
                                    className={`relative mb-16 flex flex-col md:flex-row items-start md:items-center ${index % 2 === 0 ? "md:justify-start" : "md:justify-end"}`}
                                >

                                    {/* STEP NUMBER */}
                                    <div className="absolute left-0 md:left-1/2 transform md:-translate-x-1/2  w-10 h-10 rounded-full bg-primary-blue-600 text-white  flex items-center justify-center text-sm font-semibold shadow-md">
                                        {(index + 1).toString().padStart(2, "0")}
                                    </div>

                                    {/* CONTENT CARD */}
                                    <div
                                        className={`mt-14 md:mt-0 md:w-[45%] w-full  bg-primary-blue-600 text-white rounded-2xl p-6 shadow-sm  transition-all duration-300 hover:shadow-xl hover:-translate-y-1`}
                                    >
                                        <p className="text-white leading-relaxed text-sm md:text-base">
                                            {item}
                                        </p>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* DOCUMENT REQUIREMENTS */}
                    <div>
                        <h2
                            data-aos="fade-up"
                            className="text-2xl font-semibold text-primary-blue-900 mb-10"
                        >
                            {language === "id" ? "Persyaratan Dokumen" : "Document Requirements"}
                        </h2>

                        <div className="flex flex-wrap justify-center gap-8 text-left">
                            {requirements.map((req, index) => (
                                <div
                                    key={index}
                                    data-aos="fade-up"
                                    data-aos-delay={index * 100}
                                    className="
                w-full
                sm:w-[calc(33.333%-1.34rem)]
                bg-white rounded-xl border border-gray-200 p-6
                transition-all duration-300 ease-in-out
                hover:shadow-xl hover:scale-105
            "
                                >
                                    <h4 className="font-semibold text-primary-blue-900 mb-4">
                                        {req.title}
                                    </h4>

                                    <ul className="space-y-2">
                                        {req.items.map((item, i) => (
                                            <li
                                                key={i}
                                                className="flex gap-2 text-gray-600"
                                            >
                                                <span className="text-primary-blue-600 font-bold">
                                                    {i + 1}.
                                                </span>
                                                {item}
                                            </li>
                                        ))}
                                    </ul>
                                </div>
                            ))}
                        </div>
                    </div>

                </div>
            </section>
        </div>
    );
}